package com.lyx.ctj.test;

import com.lyx.utils.FastJsonUtils;

import java.io.UnsupportedEncodingException;

/**
 * @author lvyunxiao
 * @date 2024/7/17
 * @description
 */
public class GetBytesDemo {

	public static void main(String[] args) throws UnsupportedEncodingException {
		String str = "<VoucherBody AdmDivCode=\"620000\" StYear=\"&{StYear}\" VtCode=\"&{VtCode}\" VoucherNo=\"&{VoucherNo}\">\n" +
				"      <VoucherFlag>0</VoucherFlag>\n" +
				"      <Return_Reason></Return_Reason>\n" +
				"      <Attach></Attach>\n" +
				"      <SupplementFlag>0</SupplementFlag>\n" +
				"      <Voucher></Voucher></VoucherBody>";

		String str1 = "";

		byte[] strBytes = str.getBytes("gbk");
		System.out.println("++++++++++");
		System.out.println(FastJsonUtils.toJSONNoFeatures(strBytes));
		System.out.println(new String(strBytes));
		System.out.println("++++++++++");
		System.out.println(new String(str1));
	}
}
